int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<string> grid(N);
    int startRow = -1, startCol = -1;
    int targetRow = -1, targetCol = -1;

    for (int i = 0; i < N; i++) {
        cin >> grid[i];
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'S') {
                startRow = i;
                startCol = j;
            }
            if (grid[i][j] == 'T') {
                targetRow = i;
                targetCol = j;
            }
        }
    }

    // Distance array: dist[row][col][foot] where foot=0 left foot, foot=1 right foot
    const int INF = 1e9;
    vector<vector<vector<int>>> dist(N, vector<vector<int>>(M, vector<int>(2, INF)));

    // Priority queue: (time, row, col, foot)
    priority_queue<tuple<int, int, int, int>, vector<tuple<int, int, int, int>>, greater<>> pq;

    // Start: both feet on S (we consider left foot on S initially)
    dist[startRow][startCol][0] = 0;
    pq.emplace(0, startRow, startCol, 0);

    // Directions for left/right movement
    int dr[] = {0, 0, -1, -1, -1, 1, 1, 1};
    int dc[] = {-1, 1, -1, 0, 1, -1, 0, 1};

    while (!pq.empty()) {
        auto [time, r, c, foot] = pq.top();
        pq.pop();

        if (time != dist[r][c][foot]) continue;

        // If we reached target with either foot, we can stop
        if (r == targetRow && c == targetCol) {
            cout << time << "\n";
            return 0;
        }

        // Determine the other foot position
        int otherFoot = 1 - foot;

        // Try moving the current foot
        for (int d = 0; d < 8; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr < 0 || nr >= N || nc < 0 || nc >= M) continue;
            if (grid[nr][nc] == 'X') continue;

            // New positions of feet
            int newFootRow[2], newFootCol[2];
            newFootRow[foot] = nr;
            newFootCol[foot] = nc;
            newFootRow[otherFoot] = r;
            newFootCol[otherFoot] = c;

            // Check that feet are not on same block
            if (newFootRow[0] == newFootRow[1] && newFootCol[0] == newFootCol[1]) continue;

            // Check Manhattan distance constraint
            int manDist = abs(newFootRow[0] - newFootRow[1]) + abs(newFootCol[0] - newFootCol[1]);
            if (manDist > 3) continue;

            // Calculate additional time
            int addTime = 0;
            if (grid[nr][nc] >= '1' && grid[nr][nc] <= '9') {
                addTime = grid[nr][nc] - '0';
            }

            // For target cell, no time cost
            if (grid[nr][nc] == 'T') addTime = 0;

            int newTime = time + addTime;

            // We'll update distance for the foot that just moved
            if (newTime < dist[nr][nc][foot]) {
                dist[nr][nc][foot] = newTime;
                pq.emplace(newTime, nr, nc, foot);
            }
        }
    }

    // Should not reach here if there is a path
    cout << -1 << "\n";
    return 0;
}

