/*
The statement provided is incomplete, but this is the classic "cliff climbing"
state-space shortest path problem where:
- Grid cells contain:
    'S' : possible starting cells on the bottom row
    'T' : target cells on the top row
    'X' : blocked
    '1'..'9' : cost to step on that cell
- Jack uses two feet. A state is a pair of footholds (cells).
- He may move one foot at a time onto another valid block, while the other foot
  stays fixed.
- The Euclidean distance between the two feet must not exceed a given limit D.
- Initial states are pairs of bottom-row 'S' cells within distance D.
- Goal: any state with at least one foot on a top-row 'T' cell.
- Cost of a move is the slippery value of the destination cell.

Input format assumed:
R C D
R lines of the grid

If no route exists, output -1.

This is solved with Dijkstra over all valid ordered pairs of cells.

Because the original statement fragment does not include the exact input format,
this solution follows the standard interpretation above.
*/

struct Node {
    long long dist;
    int a, b;
    bool operator<(const Node& other) const {
        return dist > other.dist;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C, D;
    if (!(cin >> R >> C >> D)) return 0;

    vector<string> g(R);
    for (int i = 0; i < R; ++i) cin >> g[i];

    vector<pair<int,int>> cells;
    vector<vector<int>> id(R, vector<int>(C, -1));
    vector<int> cost;
    vector<int> isTopT, isBottomS;

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            if (g[i][j] != 'X') {
                id[i][j] = (int)cells.size();
                cells.push_back({i, j});
                if (g[i][j] >= '1' && g[i][j] <= '9') cost.push_back(g[i][j] - '0');
                else cost.push_back(0);
                isTopT.push_back(i == 0 && g[i][j] == 'T');
                isBottomS.push_back(i == R - 1 && g[i][j] == 'S');
            }
        }
    }

    int N = (int)cells.size();
    if (N == 0) {
        cout << -1 << '\n';
        return 0;
    }

    long long D2 = 1LL * D * D;

    auto within = [&](int u, int v) {
        long long dx = cells[u].first - cells[v].first;
        long long dy = cells[u].second - cells[v].second;
        return dx * dx + dy * dy <= D2;
    };

    vector<vector<int>> nearList(N);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (i != j && within(i, j)) nearList[i].push_back(j);
        }
    }

    const long long INF = (1LL << 60);
    vector<long long> dist(1LL * N * N, INF);

    auto idx = [&](int a, int b) -> long long {
        return 1LL * a * N + b;
    };

    priority_queue<Node> pq;

    // Initial states: both feet on bottom-row S cells, distinct, within distance D.
    for (int a = 0; a < N; ++a) if (isBottomS[a]) {
        for (int b = 0; b < N; ++b) if (a != b && isBottomS[b] && within(a, b)) {
            long long &cur = dist[idx(a, b)];
            if (0 < cur) {
                cur = 0;
                pq.push({0, a, b});
            }
        }
    }

    // Edge case: if a bottom S is also top T (single row weird case), but two-foot
    // start still required by this model. If no valid initial pair exists, answer -1.

    long long ans = INF;

    while (!pq.empty()) {
        auto [d, a, b] = pq.top();
        pq.pop();
        if (d != dist[idx(a, b)]) continue;

        if (isTopT[a] || isTopT[b]) {
            ans = d;
            break;
        }

        // Move foot at a to na, keep b fixed
        for (int na : nearList[b]) {
            if (na == b || na == a) continue;
            long long nd = d + cost[na];
            long long &ref = dist[idx(na, b)];
            if (nd < ref) {
                ref = nd;
                pq.push({nd, na, b});
            }
        }

        // Move foot at b to nb, keep a fixed
        for (int nb : nearList[a]) {
            if (nb == a || nb == b) continue;
            long long nd = d + cost[nb];
            long long &ref = dist[idx(a, nb)];
            if (nd < ref) {
                ref = nd;
                pq.push({nd, a, nb});
            }
        }
    }

    cout << (ans == INF ? -1 : ans) << '\n';
    return 0;
}

#include <stdio.h>
#include <string.h>
