#define MAXN 105
#define MAXM 105
#define INF 1e9

char grid[MAXN][MAXM];
int N, M;
double dist[MAXN][MAXM][MAXM];

int cost(int r, int c) {
    if (grid[r][c] == 'X') return -1;
    if (grid[r][c] == 'S' || grid[r][c] == 'T') return 0;
    return grid[r][c] - '0';
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < N; i++) scanf("%s", grid[i]);

    for (int i = 0; i < N; i++)
        for (int j = 0; j < M; j++)
            for (int k = 0; k < M; k++)
                dist[i][j][k] = INF;

    // Initialize from bottom row (row N-1)
    for (int j = 0; j < M; j++) {
        for (int k = j; k < M; k++) {
            int cj = cost(N-1, j), ck = cost(N-1, k);
            if (cj < 0 || ck < 0) continue;
            dist[N-1][j][k] = cj + ck;
        }
    }

    // DP upward
    for (int r = N-2; r >= 0; r--) {
        for (int j = 0; j < M; j++) {
            for (int k = j; k < M; k++) {
                int cj = cost(r, j), ck = cost(r, k);
                if (cj < 0 || ck < 0) continue;
                // From previous row, any (pj, pk) where feet can reach
                for (int pj = 0; pj < M; pj++) {
                    for (int pk = pj; pk < M; pk++) {
                        if (dist[r+1][pj][pk] >= INF) continue;
                        double nd = dist[r+1][pj][pk] + cj + ck;
                        if (nd < dist[r][j][k]) dist[r][j][k] = nd;
                    }
                }
            }
        }
    }

    double ans = INF;
    for (int j = 0; j < M; j++)
        for (int k = j; k < M; k++)
            if (grid[0][j] == 'T' && grid[0][k] == 'T')
                if (dist[0][j][k] < ans) ans = dist[0][j][k];

    printf("%.0f\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXR 105
#define MAXC 105

int R, C;
char grid[MAXR][MAXC];
int dist[MAXR][MAXC];
int visited[MAXR][MAXC];

typedef struct {
    int r, c, d;
} Node;

Node heap[MAXR * MAXC * 10];
int hsize;

void push(int r, int c, int d) {
    int i = hsize++;
    heap[i].r = r; heap[i].c = c; heap[i].d = d;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].d <= heap[i].d) break;
        Node tmp = heap[p]; heap[p] = heap[i]; heap[i] = tmp;
        i = p;
    }
}

Node pop() {
    Node ret = heap[0];
    heap[0] = heap[--hsize];
    int i = 0;
    while (1) {
        int left = 2*i + 1, right = 2*i + 2, smallest = i;
        if (left < hsize && heap[left].d < heap[smallest].d) smallest = left;
        if (right < hsize && heap[right].d < heap[smallest].d) smallest = right;
        if (smallest == i) break;
        Node tmp = heap[i]; heap[i] = heap[smallest]; heap[smallest] = tmp;
        i = smallest;
    }
    return ret;
}

int is_valid(int r, int c) {
    return r >= 0 && r < R && c >= 0 && c < C && grid[r][c] != 'X';
}

int main() {
    scanf("%d %d", &R, &C);
    for (int i = 0; i < R; i++) {
        scanf("%s", grid[i]);
    }

    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            dist[i][j] = INT_MAX;

    // Initialize start states: bottom row (R-1), pairs (c, c+1) both not 'X'
    int start_row = R - 1;
    for (int c = 0; c + 1 < C; c++) {
        if (grid[start_row][c] != 'X' && grid[start_row][c+1] != 'X') {
            int cost = (grid[start_row][c] - '0') + (grid[start_row][c+1] - '0');
            if (grid[start_row][c] == 'S') cost = 0;
            if (grid[start_row][c+1] == 'S') cost = 0;
            // If both 'S', cost = 0 anyway
            if (grid[start_row][c] == 'S' && grid[start_row][c+1] == 'S') cost = 0;
            dist[start_row][c] = cost;
            push(start_row, c, cost);
        }
    }

    int dr[] = {0, 0};
    int dc[] = {-1, 1};

    while (hsize > 0) {
        Node cur = pop();
        int r = cur.r, c = cur.c, d = cur.d;
        if (visited[r][c]) continue;
        visited[r][c] = 1;
        if (r == 0) continue; // reached top, but we can still process for other paths

        // Move left foot
        for (int k = 0; k < 2; k++) {
            int nc = c + dc[k];
            if (is_valid(r, nc) && is_valid(r, nc+1)) {
                int nd = d + (grid[r][nc] - '0');
                if (nd < dist[r][nc]) {
                    dist[r][nc] = nd;
                    push(r, nc, nd);
                }
            }
        }
        // Move right foot
        for (int k = 0; k < 2; k++) {
            int nc2 = c + 1 + dc[k];
            if (is_valid(r, nc2-1) && is_valid(r, nc2)) {
                int nd = d + (grid[r][nc2] - '0');
                if (nd < dist[r][nc2-1]) {
                    dist[r][nc2-1] = nd;
                    push(r, nc2-1, nd);
                }
            }
        }
        // Move up
        if (r > 0) {
            int nr = r - 1;
            if (is_valid(nr, c) && is_valid(nr, c+1)) {
                int nd = d + (grid[nr][c] - '0') + (grid[nr][c+1] - '0');
                if (nd < dist[nr][c]) {
                    dist[nr][c] = nd;
                    push(nr, c, nd);
                }
            }
        }
    }

    int ans = INT_MAX;
    for (int c = 0; c + 1 < C; c++) {
        if (grid[0][c] == 'T' || grid[0][c+1] == 'T') {
            if (dist[0][c] < ans) ans = dist[0][c];
        }
    }
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
