typedef long long ll;

typedef struct {
    int to, next;
    ll w;
} Edge;

typedef struct {
    ll d;
    int v;
} HeapNode;

static void heap_push(HeapNode *heap, int *sz, ll d, int v) {
    int i = ++(*sz);
    heap[i].d = d;
    heap[i].v = v;
    while (i > 1) {
        int p = i >> 1;
        if (heap[p].d <= heap[i].d) break;
        HeapNode t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
    }
}

static HeapNode heap_pop(HeapNode *heap, int *sz) {
    HeapNode ret = heap[1];
    heap[1] = heap[(*sz)--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, s = i;
        if (l <= *sz && heap[l].d < heap[s].d) s = l;
        if (r <= *sz && heap[r].d < heap[s].d) s = r;
        if (s == i) break;
        HeapNode t = heap[i];
        heap[i] = heap[s];
        heap[s] = t;
        i = s;
    }
    return ret;
}

int main() {
    int R, C, K;
    if (scanf("%d %d %d", &R, &C, &K) != 3) return 0;

    char **g = (char **)malloc(R * sizeof(char *));
    for (int i = 0; i < R; i++) {
        g[i] = (char *)malloc((C + 5) * sizeof(char));
        scanf("%s", g[i]);
    }

    int **id = (int **)malloc(R * sizeof(int *));
    for (int i = 0; i < R; i++) {
        id[i] = (int *)malloc(C * sizeof(int));
        for (int j = 0; j < C; j++) id[i][j] = -1;
    }

    int n = 0;
    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (g[i][j] != 'X') id[i][j] = n++;
        }
    }

    int maxEdges = n * (2 * K + 4) + 10;
    Edge *edges = (Edge *)malloc(maxEdges * sizeof(Edge));
    int *head = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) head[i] = -1;
    int ec = 0;

    #define ADD(u,v,w) do { \
        edges[ec].to = (v); \
        edges[ec].w = (w); \
        edges[ec].next = head[(u)]; \
        head[(u)] = ec++; \
    } while(0)

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < C; j++) {
            if (g[i][j] == 'X') continue;
            int u = id[i][j];

            for (int d = -K; d <= K; d++) {
                if (d == 0) continue;
                int nj = j + d;
                if (0 <= nj && nj < C && g[i][nj] != 'X') {
                    int v = id[i][nj];
                    ll cost = (g[i][nj] >= '1' && g[i][nj] <= '9') ? (g[i][nj] - '0') : 0;
                    ADD(u, v, cost);
                }
            }

            if (i > 0 && g[i - 1][j] != 'X') {
                int v = id[i - 1][j];
                ll cost = (g[i - 1][j] >= '1' && g[i - 1][j] <= '9') ? (g[i - 1][j] - '0') : 0;
                ADD(u, v, cost);
            }
            if (i + 1 < R && g[i + 1][j] != 'X') {
                int v = id[i + 1][j];
                ll cost = (g[i + 1][j] >= '1' && g[i + 1][j] <= '9') ? (g[i + 1][j] - '0') : 0;
                ADD(u, v, cost);
            }
        }
    }

    ll *dist = (ll *)malloc(n * sizeof(ll));
    for (int i = 0; i < n; i++) dist[i] = LLONG_MAX / 4;

    HeapNode *heap = (HeapNode *)malloc((ec + n + 10) * sizeof(HeapNode));
    int hsz = 0;

    for (int j = 0; j < C; j++) {
        if (g[R - 1][j] == 'S') {
            int s = id[R - 1][j];
            dist[s] = 0;
            heap_push(heap, &hsz, 0, s);
        }
    }

    while (hsz) {
        HeapNode cur = heap_pop(heap, &hsz);
        ll d = cur.d;
        int u = cur.v;
        if (d != dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(heap, &hsz, nd, v);
            }
        }
    }

    ll ans = LLONG_MAX / 4;
    for (int j = 0; j < C; j++) {
        if (g[0][j] == 'T') {
            int t = id[0][j];
            if (t != -1 && dist[t] < ans) ans = dist[t];
        }
    }

    if (ans >= LLONG_MAX / 8) printf("-1\n");
    else printf("%lld\n", ans);

    return 0;
}

import java.io.*;
import java.util.*;

public class Solution {
    static class Cell implements Comparable<Cell> {
        int row, col, time;

        Cell(int row, int col, int time) {
            this.row = row;
            this.col = col;
            this.time = time;
        }

        @Override
        public int compareTo(Cell other) {
            return Integer.compare(this.time, other.time);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions
        String[] firstLine = br.readLine().split(" ");
        int R = Integer.parseInt(firstLine[0]);
        int C = Integer.parseInt(firstLine[1]);

        char[][] grid = new char[R][C];
        int[][] time = new int[R][C];

        // Find start and target positions
        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        for (int i = 0; i < R; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < C; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                    grid[i][j] = '0'; // Start has 0 time cost
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                    grid[i][j] = '0'; // Target has 0 time cost
                }
            }
        }

        // Dijkstra's algorithm
        int[][] dist = new int[R][C];
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<Cell> pq = new PriorityQueue<>();
        dist[startRow][startCol] = 0;
        pq.offer(new Cell(startRow, startCol, 0));

        // Direction arrays for up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!pq.isEmpty()) {
            Cell current = pq.poll();
            int r = current.row;
            int c = current.col;
            int currTime = current.time;

            if (currTime > dist[r][c]) continue;

            // If we reached target, we can stop (first time we pop it, it's optimal)
            if (r == targetRow && c == targetCol) {
                System.out.println(currTime);
                return;
            }

            // Try all 4 directions
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds and if not blocked
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] != 'X') {
                    int newTime = currTime;
                    if (grid[nr][nc] >= '1' && grid[nr][nc] <= '9') {
                        newTime += (grid[nr][nc] - '0');
                    }
                    // '0' for start/target has no additional cost

                    if (newTime < dist[nr][nc]) {
                        dist[nr][nc] = newTime;
                        pq.offer(new Cell(nr, nc, newTime));
                    }
                }
            }
        }

        // If no path found
        System.out.println("-1");
    }
}

