public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rows = sc.nextInt(), cols = sc.nextInt();
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) grid[i] = sc.next().toCharArray();

        // State: (r1,c1,r2,c2) - positions of two feet
        // Start: both feet on 'S' cells in bottom row (row rows-1)
        // End: at least one foot on 'T' cell in top row (row 0)

        int INF = Integer.MAX_VALUE/2;
        // Use Dijkstra
        // State encoded as r1*cols^3 + c1*cols^2 + r2*cols + c2... use map
        Map<Long, Integer> dist = new HashMap<>();
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));

        int bottomRow = rows - 1;
        List<Integer> starts = new ArrayList<>();
        for (int c = 0; c < cols; c++) if (grid[bottomRow][c] == 'S') starts.add(c);

        for (int c1 : starts) for (int c2 : starts) {
            if (c1 != c2) {
                long state = encode(bottomRow, c1, bottomRow, c2, rows, cols);
                if (!dist.containsKey(state)) { dist.put(state, 0); pq.offer(new long[]{0, bottomRow, c1, bottomRow, c2}); }
            }
        }

        int[][] dirs = {{-1,0},{0,-1},{0,1}};
        int ans = INF;
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int cost=(int)cur[0], r1=(int)cur[1], c1=(int)cur[2], r2=(int)cur[3], c2=(int)cur[4];
            long key = encode(r1,c1,r2,c2,rows,cols);
            if (dist.getOrDefault(key,INF) < cost) continue;
            if (grid[r1][c1]=='T' || grid[r2][c2]=='T') { ans=cost; break; }
            for (int[][] foot : new int[][][]{{{r1,c1},{r2,c2}},{{r2,c2},{r1,c1}}}) {
                for (int[] d : dirs) {
                    int nr=foot[0][0]+d[0], nc=foot[0][1]+d[1];
                    if (nr<0||nr>=rows||nc<0||nc>=cols) continue;
                    if (grid[nr][nc]=='X'||grid[nr][nc]=='S') continue;
                    if (nr==foot[1][0]&&nc==foot[1][1]) continue;
                    if (Math.abs(nc-foot[1][1])>3) continue;
                    int ncost=cost+(grid[nr][nc]=='T'?0:grid[nr][nc]-'0');
                    long nkey=encode(nr,nc,foot[1][0],foot[1][1],rows,cols);
                    if (ncost<dist.getOrDefault(nkey,INF)) { dist.put(nkey,ncost); pq.offer(new long[]{ncost,nr,nc,foot[1][0],foot[1][1]}); }
                }
            }
        }
        System.out.println(ans==INF?-1:ans);
    }
    static long encode(int r1,int c1,int r2,int c2,int R,int C){return((long)r1*C+c1)*(long)(R*C)+r2*C+c2;}
}

