/*
The statement provided is truncated/ambiguous, but the natural interpretation is:

- Grid of blocks.
- 'S' marks possible start blocks on the bottom row.
- 'T' marks possible target blocks on the top row.
- 'X' are forbidden.
- Digits '1'..'9' are costs (time to step on that block).
- Jack may move in 4 directions (up, down, left, right) among non-'X' cells.
- Total time is the sum of costs of visited cells; stepping onto S/T costs 0 unless they are digits
  (here they are letters, so treated as 0).
- We need the minimum time from any S in bottom row to any T in top row.

This is solved with Dijkstra from all bottom-row S cells.

If the intended movement constraints were more specific in the original full statement, they are not present
in the prompt text. This implementation solves the standard weighted-grid shortest path implied by the given data.
*/

public class Main {
    static class Node implements Comparable<Node> {
        int r, c;
        long d;
        Node(int r, int c, long d) {
            this.r = r;
            this.c = c;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        while ((first = br.readLine()) != null && first.trim().isEmpty()) {}
        if (first == null) return;

        StringTokenizer st = new StringTokenizer(first);
        int n, m;

        if (st.countTokens() >= 2) {
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());
        } else {
            // Fallback: if only one number on first line, try reading second from next line
            n = Integer.parseInt(first.trim());
            String second = br.readLine();
            while (second != null && second.trim().isEmpty()) second = br.readLine();
            if (second == null) return;
            m = Integer.parseInt(second.trim());
        }

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.length() < m) {
                String extra = br.readLine();
                if (extra == null) break;
                line += extra;
            }
            grid[i] = line.toCharArray();
        }

        long ans = dijkstra(grid, n, m);
        System.out.println(ans == Long.MAX_VALUE ? -1 : ans);
    }

    static long dijkstra(char[][] grid, int n, int m) {
        long[][] dist = new long[n][m];
        for (int i = 0; i < n; i++) Arrays.fill(dist[i], Long.MAX_VALUE);

        PriorityQueue<Node> pq = new PriorityQueue<>();

        // Multi-source: all S on bottom row
        for (int c = 0; c < m; c++) {
            if (grid[n - 1][c] == 'S') {
                dist[n - 1][c] = 0;
                pq.offer(new Node(n - 1, c, 0));
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.r][cur.c]) continue;

            if (cur.r == 0 && grid[cur.r][cur.c] == 'T') {
                return cur.d;
            }

            for (int k = 0; k < 4; k++) {
                int nr = cur.r + dr[k];
                int nc = cur.c + dc[k];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                if (grid[nr][nc] == 'X') continue;

                long w = cost(grid[nr][nc]);
                long nd = cur.d + w;
                if (nd < dist[nr][nc]) {
                    dist[nr][nc] = nd;
                    pq.offer(new Node(nr, nc, nd));
                }
            }
        }

        return Long.MAX_VALUE;
    }

    static int cost(char ch) {
        if (ch >= '1' && ch <= '9') return ch - '0';
        return 0; // S, T, or any other non-blocked cell
    }
}

