import sys
import heapq

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    first = data[0].split()
    if len(first) < 2:
        return
    n, m = map(int, first[:2])

    grid = [list(data[i + 1].rstrip()) for i in range(n)]

    # Cost of stepping on a cell
    def cell_cost(ch):
        if ch in '123456789':
            return int(ch)
        if ch == 'S' or ch == 'T':
            return 0
        return None  # X or invalid

    # Dijkstra on states:
    # state = (r, l, rr) where r is row, l/rr are columns of left/right foot on that row
    # Both feet must be on valid cells of the same row and 1 <= rr-l <= 3.
    #
    # Transitions:
    # - Move one foot left/right on same row, keeping feet distance in [1,3]
    # - Move one foot up to next row, onto a valid cell, again keeping distance in [1,3]
    #
    # Start: any valid pair on bottom row containing at least one 'S'
    # Goal: any state on top row containing at least one 'T'

    INF = 10**18
    dist = {}
    pq = []

    bottom = n - 1

    # Initial states
    for l in range(m):
        if cell_cost(grid[bottom][l]) is None:
            continue
        for rr in range(l + 1, min(m, l + 4)):
            if cell_cost(grid[bottom][rr]) is None:
                continue
            if grid[bottom][l] == 'S' or grid[bottom][rr] == 'S':
                init_cost = cell_cost(grid[bottom][l]) + cell_cost(grid[bottom][rr])
                state = (bottom, l, rr)
                if init_cost < dist.get(state, INF):
                    dist[state] = init_cost
                    heapq.heappush(pq, (init_cost, bottom, l, rr))

    ans = INF

    while pq:
        d, r, l, rr = heapq.heappop(pq)
        if d != dist.get((r, l, rr), INF):
            continue

        if r == 0 and (grid[r][l] == 'T' or grid[r][rr] == 'T'):
            ans = d
            break

        # Move left foot on same row
        for nl in (l - 1, l + 1):
            if 0 <= nl < m and nl < rr and 1 <= rr - nl <= 3:
                c = cell_cost(grid[r][nl])
                if c is not None:
                    nd = d + c
                    st = (r, nl, rr)
                    if nd < dist.get(st, INF):
                        dist[st] = nd
                        heapq.heappush(pq, (nd, r, nl, rr))

        # Move right foot on same row
        for nrr in (rr - 1, rr + 1):
            if 0 <= nrr < m and l < nrr and 1 <= nrr - l <= 3:
                c = cell_cost(grid[r][nrr])
                if c is not None:
                    nd = d + c
                    st = (r, l, nrr)
                    if nd < dist.get(st, INF):
                        dist[st] = nd
                        heapq.heappush(pq, (nd, r, l, nrr))

        # Move left foot up
        if r > 0:
            nr = r - 1
            for nl in range(max(0, rr - 3), rr):
                if 1 <= rr - nl <= 3:
                    c = cell_cost(grid[nr][nl])
                    if c is not None:
                        nd = d + c
                        st = (nr, nl, rr)
                        if nd < dist.get(st, INF):
                            dist[st] = nd
                            heapq.heappush(pq, (nd, nr, nl, rr))

            # Move right foot up
            for nrr in range(l + 1, min(m, l + 4)):
                if 1 <= nrr - l <= 3:
                    c = cell_cost(grid[nr][nrr])
                    if c is not None:
                        nd = d + c
                        st = (nr, l, nrr)
                        if nd < dist.get(st, INF):
                            dist[st] = nd
                            heapq.heappush(pq, (nd, nr, l, nrr))

    print(ans if ans < INF else -1)

